"""Fill blank cells of a target column with the last non-blank prefix above them
plus a sequential bijective base-26 lowercase-letter suffix (a, b, ..., z, aa, ab, ...).
The suffix counter restarts at 'a' for every maximal run of consecutive blanks.
Pre-existing non-blank cells and all other columns are preserved verbatim.

Entry point:  run(ctx, inputs) -> {"status": "ok"|"not_found"|"needs_input"|"blocked",
                                   "outputs": {...}}
"""

import os
import glob


def _suffix_for(i):
    """Bijective base-26: 1->a, 2->b, ..., 26->z, 27->aa, 28->ab, ..."""
    s = ""
    while i > 0:
        i, rem = divmod(i - 1, 26)
        s = chr(97 + rem) + s
    return s


def _is_blank(v):
    return v is None or (isinstance(v, str) and v.strip() == "")


def _norm_prefix(p):
    if isinstance(p, bool):
        return str(p)
    if isinstance(p, float) and p.is_integer():
        return str(int(p))
    if isinstance(p, int):
        return str(p)
    return str(p)


def _col_index(letter):
    if isinstance(letter, int):
        return letter if letter > 0 else 1
    idx = 0
    for ch in str(letter).strip():
        if ch.isalpha():
            idx = idx * 26 + (ord(ch.upper()) - 64)
    return idx if idx > 0 else 1


def _resolve_input(inputs):
    inp = inputs.get("input_path") or inputs.get("input_file")
    if not inp:
        inp = os.environ.get("INPUT_PATH")
    if inp and os.path.exists(inp):
        return inp
    cands = []
    for pat in ("/workspace/inputs/*.xlsx", "/workspace/inputs/*.xlsm",
                "inputs/*.xlsx", "inputs/*.xlsm",
                "/workspace/*.xlsx", "*.xlsx", "*.xlsm"):
        cands.extend(sorted(glob.glob(pat)))
    seen = set()
    for c in cands:
        if c not in seen:
            seen.add(c)
            return c
    return None


def _resolve_output(inputs):
    outp = inputs.get("output_path") or inputs.get("output_file")
    if not outp:
        outp = os.environ.get("OUTPUT_PATH")
    if not outp:
        outp = "case1_result.xlsx"
    return outp


def run(ctx, inputs):
    outputs = {
        "output_path": "",
        "files": [],
        "filled_count": 0,
        "blank_remaining": 0,
        "mismatch_count": 0,
        "verification": "FAIL",
    }

    def log(msg):
        try:
            if ctx is not None and hasattr(ctx, "observe"):
                ctx.observe(msg)
        except Exception:
            pass
        try:
            print(msg)
        except Exception:
            pass

    if not isinstance(inputs, dict):
        inputs = {}

    inp = _resolve_input(inputs)
    if not inp:
        log("ERROR: no readable input workbook found")
        return {"status": "not_found", "outputs": outputs}
    log("input workbook: %s" % inp)

    outp = _resolve_output(inputs)
    log("requested output: %s" % outp)

    try:
        import openpyxl
    except Exception as exc:
        log("ERROR: openpyxl unavailable: %r" % (exc,))
        return {"status": "blocked", "outputs": outputs}

    sheet_name = inputs.get("sheet_name")
    target_column = inputs.get("target_column", "A")
    header_row = inputs.get("header_row", 1)
    try:
        header_row = int(header_row)
    except Exception:
        header_row = 1
    if header_row < 1:
        header_row = 1
    tcol = _col_index(target_column)

    try:
        wb = openpyxl.load_workbook(inp)
    except Exception as exc:
        log("ERROR: cannot load workbook: %r" % (exc,))
        return {"status": "blocked", "outputs": outputs}

    names = list(wb.sheetnames)
    if sheet_name and sheet_name in names:
        ws = wb[sheet_name]
    else:
        ws = wb[names[0]]
    log("sheet=%r max_row=%d max_col=%d target_col=%s header_row=%d"
        % (ws.title, ws.max_row, ws.max_column, target_column, header_row))

    max_row = ws.max_row
    max_col = ws.max_column

    # data region = last row holding any content across the used columns
    data_last = header_row
    for r in range(1, max_row + 1):
        for c in range(1, max_col + 1):
            if not _is_blank(ws.cell(row=r, column=c).value):
                data_last = r
                break
    if data_last < header_row:
        data_last = max_row

    # snapshot originals BEFORE mutating
    orig_col = {}
    for r in range(1, data_last + 1):
        orig_col[r] = ws.cell(row=r, column=tcol).value
    others = {}
    for r in range(1, data_last + 1):
        for c in range(1, max_col + 1):
            if c != tcol:
                others[(r, c)] = ws.cell(row=r, column=c).value

    # ---- transform ----
    filled = 0
    prefix = None
    r = header_row + 1
    while r <= data_last:
        v = ws.cell(row=r, column=tcol).value
        if not _is_blank(v):
            prefix = v
            r += 1
            continue
        start = r
        while r <= data_last and _is_blank(ws.cell(row=r, column=tcol).value):
            r += 1
        if prefix is None:
            log("WARNING: blank run rows %d-%d has no non-blank value above; left untouched"
                % (start, r - 1))
            continue
        base = _norm_prefix(prefix)
        for k, row in enumerate(range(start, r), start=1):
            ws.cell(row=row, column=tcol).value = base + _suffix_for(k)
            filled += 1

    # ---- save ----
    written = []
    try:
        d = os.path.dirname(os.path.abspath(outp))
        if d and not os.path.isdir(d):
            os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    try:
        wb.save(outp)
        written.append(outp)
    except Exception as exc:
        log("ERROR: save failed at %s: %r" % (outp, exc))
        try:
            alt = os.path.basename(outp) or "case1_result.xlsx"
            wb.save(alt)
            outp = alt
            written.append(alt)
        except Exception as exc2:
            log("ERROR: fallback save failed: %r" % (exc2,))
            return {"status": "blocked", "outputs": outputs}

    # extra relative copy when the primary path is absolute elsewhere
    try:
        base_name = os.path.basename(outp)
        if base_name and os.path.abspath(base_name) != os.path.abspath(outp):
            wb.save(base_name)
            if base_name not in written:
                written.append(base_name)
    except Exception:
        pass

    outputs["output_path"] = outp
    outputs["files"] = written
    log("saved: %s copies=%r" % (outp, written))

    # ---- verify by reloading the saved workbook ----
    try:
        wbv = openpyxl.load_workbook(outp)
    except Exception as exc:
        log("ERROR: cannot reload output: %r" % (exc,))
        outputs["filled_count"] = filled
        return {"status": "blocked", "outputs": outputs}
    if ws.title in wbv.sheetnames:
        wsv = wbv[ws.title]
    else:
        wsv = wbv[wbv.sheetnames[0]]

    # independently recompute expected target-column values from the ORIGINAL snapshot
    expected = {}
    prefix = None
    r = header_row + 1
    while r <= data_last:
        ov = orig_col.get(r)
        if not _is_blank(ov):
            prefix = ov
            expected[r] = ov
            r += 1
            continue
        start = r
        while r <= data_last and _is_blank(orig_col.get(r)):
            r += 1
        if prefix is None:
            for row in range(start, r):
                expected[row] = None
        else:
            base = _norm_prefix(prefix)
            for k, row in enumerate(range(start, r), start=1):
                expected[row] = base + _suffix_for(k)

    mismatches = 0
    for r in range(1, data_last + 1):
        exp = expected.get(r, orig_col.get(r))
        got = wsv.cell(row=r, column=tcol).value
        if _is_blank(exp) and _is_blank(got):
            continue
        if exp != got:
            mismatches += 1

    for (r, c), v in others.items():
        got = wsv.cell(row=r, column=c).value
        if _is_blank(v) and _is_blank(got):
            continue
        if v != got:
            mismatches += 1

    blank_remaining = 0
    for r in range(header_row + 1, data_last + 1):
        if _is_blank(wsv.cell(row=r, column=tcol).value):
            blank_remaining += 1

    outputs["filled_count"] = filled
    outputs["blank_remaining"] = blank_remaining
    outputs["mismatch_count"] = mismatches
    outputs["verification"] = "PASS" if (mismatches == 0 and blank_remaining == 0) else "FAIL"
    log("filled=%d blank_remaining=%d mismatch_count=%d verification=%s"
        % (filled, blank_remaining, mismatches, outputs["verification"]))
    return {"status": "ok", "outputs": outputs}
